package gen_test

import (
	"strings"
	"testing"
)

// TestGoldenOutput pins the full generated hook modules.
func TestGoldenOutput(t *testing.T) {
	out := generate(t, "import_extension=.js")

	checkGolden(t, "user_v1_user_react_query.ts", out["user/v1/user_react_query.ts"])
	checkGolden(t, "shipping_v1_shipping_react_query.ts", out["shipping/v1/shipping_react_query.ts"])
}

// TestFileHeader checks the stable banner the contract requires.
func TestFileHeader(t *testing.T) {
	rq := generate(t, "")["user/v1/user_react_query.ts"]

	for _, want := range []string{
		"// Code generated by protoc-gen-grpc-gateway-react-query. DO NOT EDIT.",
		"// @grpc-gateway-typescript-contract: v1",
		"// source: user/v1/user.proto",
	} {
		if !strings.Contains(rq, want) {
			t.Errorf("header is missing %q", want)
		}
	}
}

// TestQueryKeyFactory checks the exported key factory and its service scoping.
func TestQueryKeyFactory(t *testing.T) {
	rq := generate(t, "")["user/v1/user_react_query.ts"]

	if !strings.Contains(rq, "export const userServiceKeys = {") {
		t.Error("the key factory must be exported for manual invalidation")
	}
	// The service name scopes every key, so two services cannot collide.
	if !strings.Contains(rq, `all: ["UserService"] as const,`) {
		t.Error("the all key must carry the service name")
	}
}

// TestQueryKeyIncludesWholeRequest is the rule from docs/v1.md §5.5: keying on an
// id alone would serve stale data for a different filter.
func TestQueryKeyIncludesWholeRequest(t *testing.T) {
	rq := generate(t, "")["user/v1/user_react_query.ts"]

	want := `listUsers: (request: user_v1_user_type.ListUsersRequest | undefined) =>
    [...userServiceKeys.all, "listUsers", request] as const,`
	if !strings.Contains(rq, want) {
		t.Errorf("expected the whole request in the key:\n%s", want)
	}
	// A key built from a single field would look like this, and must not appear.
	if strings.Contains(rq, "request.id") {
		t.Error("keys must not narrow to a single field")
	}
}

// TestQueryHooksForGET checks that GET methods become useQuery hooks.
func TestQueryHooksForGET(t *testing.T) {
	rq := generate(t, "")["user/v1/user_react_query.ts"]

	if !strings.Contains(rq, "export function useGetUser(") {
		t.Error("a GET method must generate a useQuery hook")
	}
	if !strings.Contains(rq, "return useQuery({") {
		t.Error("the hook must call useQuery")
	}
	// The hook returns the useQuery result so React Query's inference flows
	// through untouched.
	if !strings.Contains(rq, "export function useListUsers(") {
		t.Error("a second GET method must also generate a hook")
	}
}

// TestMutationHooksForWrites checks that non-GET methods become useMutation hooks.
func TestMutationHooksForWrites(t *testing.T) {
	rq := generate(t, "")["user/v1/user_react_query.ts"]

	for _, name := range []string{"useCreateUser", "useUpdateUser"} {
		if !strings.Contains(rq, "export function "+name+"(") {
			t.Errorf("%s must be generated as a mutation hook", name)
		}
	}
	if !strings.Contains(rq, "return useMutation({") {
		t.Error("mutation hooks must call useMutation")
	}
}

// TestMutationOptionsPrecedeMutationFn checks that the generated mutationFn cannot
// be replaced: ...options comes first.
func TestMutationOptionsPrecedeMutationFn(t *testing.T) {
	rq := generate(t, "")["user/v1/user_react_query.ts"]

	idxOptions := strings.Index(rq, "return useMutation({\n    ...options,")
	if idxOptions < 0 {
		t.Fatal("expected ...options first inside useMutation")
	}
	idxFn := strings.Index(rq, "mutationFn: (request:")
	if idxFn < idxOptions {
		t.Error("mutationFn must come after ...options so it cannot be overridden")
	}
}

// TestRequestIsOptionalWithEnabled checks the enabled default, which makes
// "the id is not available yet" expressible.
func TestRequestIsOptionalWithEnabled(t *testing.T) {
	rq := generate(t, "")["user/v1/user_react_query.ts"]

	if !strings.Contains(rq, "request: user_v1_user_type.GetUserRequest | undefined,") {
		t.Error("a query hook must accept an undefined request by default")
	}
	if !strings.Contains(rq, "enabled: enabled ?? request !== undefined,") {
		t.Error("enabled must default to whether a request was supplied")
	}
	if !strings.Contains(rq, `return Promise.reject(new Error("request is required"));`) {
		t.Error("the query function must reject when it is called without a request")
	}
}

// TestRequestOptionalCanBeDisabled covers request_optional=false.
func TestRequestOptionalCanBeDisabled(t *testing.T) {
	rq := generate(t, "request_optional=false")["user/v1/user_react_query.ts"]

	if strings.Contains(rq, "| undefined,") {
		t.Error("request_optional=false must not allow an undefined request")
	}
	if !strings.Contains(rq, "enabled: enabled ?? true,") {
		t.Error("with a required request the query is enabled unless turned off")
	}
}

// TestSignalIsForwarded is the cancellation rule from docs/v1.md §5.6: without it,
// a request keeps running after the component unmounts.
func TestSignalIsForwarded(t *testing.T) {
	rq := generate(t, "")["user/v1/user_react_query.ts"]

	if !strings.Contains(rq, "queryFn: ({ signal }) => {") {
		t.Error("the query function must take the abort signal")
	}
	if !strings.Contains(rq, "return client.getUser(request, { signal });") {
		t.Error("the signal must be passed to the client")
	}
}

// TestOptionsCannotOverrideKeyOrFn checks the Omit list.
func TestOptionsCannotOverrideKeyOrFn(t *testing.T) {
	rq := generate(t, "")["user/v1/user_react_query.ts"]

	if !strings.Contains(rq, `"queryKey" | "queryFn"`) {
		t.Error("queryKey and queryFn must be omitted from the caller's options")
	}
	if !strings.Contains(rq, "const { enabled, ...rest } = options ?? {};") {
		t.Error("options must be spread so select, staleTime and the rest still work")
	}
}

// TestQueryKeysAndFnsComeAfterRest checks that ...rest cannot clobber the
// generated key and function.
func TestQueryKeysAndFnsComeAfterRest(t *testing.T) {
	rq := generate(t, "")["user/v1/user_react_query.ts"]

	idxRest := strings.Index(rq, "...rest,")
	idxKey := strings.Index(rq, "queryKey: userServiceKeys.getUser(request),")
	if idxRest < 0 || idxKey < 0 {
		t.Fatal("expected ...rest and a generated queryKey")
	}
	if idxKey < idxRest {
		t.Error("the generated queryKey must come after ...rest so it cannot be overridden")
	}
}

// TestAdditionalBindingsGenerateHooks checks the contract both plugins share:
// additional_bindings=methods produces matching hook and key names.
func TestAdditionalBindingsGenerateHooks(t *testing.T) {
	rq := generate(t, "additional_bindings=methods")["shipping/v1/shipping_react_query.ts"]

	if !strings.Contains(rq, "export function useExportShippersBinding2(") {
		t.Error("an extra binding must generate useMethodBinding2")
	}
	if !strings.Contains(rq, "exportShippersBinding2: (request:") {
		t.Error("an extra binding must generate a matching key entry")
	}
	if !strings.Contains(rq, "client.exportShippersBinding2(request, { signal })") {
		t.Error("the hook must call the matching client method")
	}
}

// TestHookPrefixService covers hook_prefix=service, the documented way to avoid
// collisions across services.
func TestHookPrefixService(t *testing.T) {
	rq := generate(t, "hook_prefix=service")["user/v1/user_react_query.ts"]

	if !strings.Contains(rq, "export function useUserServiceGetUser(") {
		t.Error("hook_prefix=service must prefix every hook with its service")
	}
	if !strings.Contains(rq, "userServiceGetUser: (request:") {
		t.Error("the key entry must be prefixed to match the hook")
	}
}

// TestQueriesOverride covers the "POST that is really a query" case.
func TestQueriesOverride(t *testing.T) {
	// Without the override, CreateUser is a mutation.
	plain := generate(t, "")["user/v1/user_react_query.ts"]
	createSection := sectionBetween(plain, "useCreateUser(", "useUpdateUser(")
	if strings.Contains(createSection, "useQuery") {
		t.Fatal("a POST must default to a mutation")
	}

	// With the override it becomes a query.
	overridden := generate(t, "queries=user.v1.UserService.CreateUser")["user/v1/user_react_query.ts"]
	createSection = sectionBetween(overridden, "useCreateUser(", "useUpdateUser(")
	if !strings.Contains(createSection, "useQuery({") {
		t.Error("queries= must force a POST method to generate useQuery")
	}
}

// TestResponseBodyDrivesHookData checks that the hook data type matches the
// response_body field, so it agrees with the Axios client's return type.
func TestResponseBodyDrivesHookData(t *testing.T) {
	rq := generate(t, "")["user/v1/user_react_query.ts"]

	if !strings.Contains(rq, "UseQueryOptions<user_v1_user_type.User, Error, user_v1_user_type.User>") {
		t.Error("response_body must drive the hook data type")
	}
}

// TestImportsAreCorrect checks the three import groups and that useQuery is a value
// import rather than a type import. import_extension is set so the specifiers match
// what a NodeNext project needs.
func TestImportsAreCorrect(t *testing.T) {
	rq := generate(t, "import_extension=.js")["user/v1/user_react_query.ts"]

	if !strings.Contains(rq, `import { useMutation, useQuery } from "@tanstack/react-query";`) {
		t.Error("useQuery and useMutation must be value imports")
	}
	if !strings.Contains(rq, `import type { UseMutationOptions, UseQueryOptions } from "@tanstack/react-query";`) {
		t.Error("the option types must be type-only imports")
	}
	if !strings.Contains(rq, `import type { UserServiceClient } from "./user_api.js";`) {
		t.Error("the client class must be imported from the matching _api file")
	}
	if !strings.Contains(rq, `import type * as user_v1_user_type from "./user_type.js";`) {
		t.Error("the types file must be imported under the contract's namespace alias")
	}
}

// TestOnlyOneGroupPerModule is a regression guard: an earlier version emitted the
// same import statement twice when a module appeared in two import groups.
func TestOnlyOneGroupPerModule(t *testing.T) {
	rq := generate(t, "")["user/v1/user_react_query.ts"]

	if n := strings.Count(rq, `from "@tanstack/react-query"`); n != 2 {
		t.Errorf("expected exactly two react-query imports (one value, one type), got %d", n)
	}
}

// TestUnusedHookImportIsOmitted checks that a module importing neither hook kind
// stays import-free, and that a query-only file does not pull in useMutation.
//
// The shipping fixture has a HEAD binding, which is a mutation, so the minimal
// query-only file is the address module: it declares no service at all and must
// therefore carry no react-query import.
func TestUnusedHookImportIsOmitted(t *testing.T) {
	address := generate(t, "")["common/v1/address_react_query.ts"]
	if strings.Contains(address, "@tanstack/react-query") {
		t.Error("a file with no service must not import react-query")
	}

	// The user file has both kinds, so both imports appear exactly once.
	user := generate(t, "")["user/v1/user_react_query.ts"]
	if n := strings.Count(user, "useQuery"); n == 0 {
		t.Error("a file with GET methods must import useQuery")
	}
	// A GET-only service must not import useMutation. Build that case by forcing
	// the two write methods to be treated as queries.
	forced := generate(t, "queries=user.v1.UserService.CreateUser,user.v1.UserService.UpdateUser")["user/v1/user_react_query.ts"]
	if strings.Contains(forced, "useMutation") {
		t.Error("when every method is a query, useMutation must not be imported")
	}
}

// TestNoTsNoCheck checks that the generated hooks are meant to type-check.
func TestNoTsNoCheck(t *testing.T) {
	for name, rq := range generate(t, "") {
		if strings.Contains(rq, "@ts-nocheck") {
			t.Errorf("%s must not contain @ts-nocheck", name)
		}
	}
}

// TestDeterministicOutput runs generation twice and requires byte equality.
func TestDeterministicOutput(t *testing.T) {
	first := generate(t, "import_extension=.js")
	second := generate(t, "import_extension=.js")

	for name, a := range first {
		if b := second[name]; a != b {
			t.Errorf("%s differs between runs", name)
		}
	}
}

// sectionBetween returns the text between two markers, for scoping assertions.
func sectionBetween(src, start, end string) string {
	i := strings.Index(src, start)
	if i < 0 {
		return ""
	}
	rest := src[i:]
	if j := strings.Index(rest, end); j >= 0 {
		return rest[:j]
	}
	return rest
}
